<script setup lang="ts">
import { computed, ref, watch, nextTick, onMounted, onBeforeUnmount } from 'vue'
import { animate, stagger } from 'motion'
import HomeCareKpi from './HomeCareKpi.vue'
import HomeCareCoverage from './HomeCareCoverage.vue'
import { careAreas,carePeople,makeCareVisits,careTime,type CareVisit } from './homecare-model'
const props=defineProps<{initialPage?:string}>()
const pages=['Dashboard','Schedule','Visits','Alerts','Caregivers','Clients','EVV','Reports','Components','Settings','Help']
const page=ref(props.initialPage||'Dashboard'),area=ref('All service areas'),query=ref(''),state=ref('Ready'),dark=ref(false),mobileNav=ref(false),visits=ref(makeCareVisits()),notice=ref(''),dismissed=ref<string[]>([]),reminded=ref(false),selectedDay=ref(5)
const root=ref<HTMLElement|null>(null),dialog=ref<HTMLDialogElement|null>(null),detail=ref<CareVisit|null>(null),kind=ref(''),clientDraft=ref(''),startDraft=ref('10'),areaDraft=ref(careAreas[0]),careDraft=ref(''),nameDraft=ref(''),validation=ref(''),settingsSaved=ref(false),agency=ref('Meadow Home Care'),notify=ref(true)
const filtered=computed(()=>visits.value.filter(v=>(area.value==='All service areas'||v.area===area.value)&&(!query.value||(v.id+' '+v.client+' '+(v.caregiver||'')+' '+v.area).toLowerCase().includes(query.value.toLowerCase()))))
const missing=computed(()=>filtered.value.filter(v=>!v.caregiver)),live=computed(()=>filtered.value.filter(v=>v.status==='in-progress')),done=computed(()=>filtered.value.filter(v=>v.status==='completed')),late=computed(()=>filtered.value.filter(v=>v.status==='late'))
const proposals=[{id:'HC-011',caregiver:'Lena Brooks',score:94},{id:'HC-014',caregiver:'Omar Chen',score:91},{id:'HC-017',caregiver:'Nia Patel',score:89}]
const replacements=computed(()=>proposals.map(p=>({...p,visit:filtered.value.find(v=>v.id===p.id)})).filter(p=>p.visit&&!p.visit.caregiver))
const alerts=computed(()=>[{id:'late',title:'Running 18 minutes late',text:'Sample arrival estimate. Review the assignment before changing it.',visit:late.value[0],action:'Reassign'},{id:'evv',title:'EVV location not verified',text:'One local visit is missing location verification.',visit:filtered.value.find(v=>!v.evv),action:'Review'},{id:'note',title:'Visit note overdue',text:'Completed visit needs a local care log.',visit:filtered.value.find(v=>v.status==='completed'&&!v.note),action:'Remind'}].filter(a=>a.visit&&!dismissed.value.includes(a.id)))
const clients=computed(()=>Array.from(new Set(filtered.value.map(v=>v.client))).sort())
const title=computed(()=>page.value==='Dashboard'?'Your day, in good hands.':page.value==='EVV'?'Visit verification':page.value==='Components'?'The care operations kit':page.value)
let animations:ReturnType<typeof animate>[]=[],media:MediaQueryList|undefined,disposed=false,generation=0,opener:HTMLElement|null=null
function stop(){animations.forEach(a=>a.stop());animations=[];root.value?.querySelectorAll<HTMLElement>('.hc-enter').forEach(e=>{e.style.opacity='';e.style.transform=''})}
async function enter(){const n=++generation;stop();await nextTick();if(disposed||n!==generation||media?.matches||!root.value)return;const els=root.value.querySelectorAll('.hc-enter');if(els.length)animations.push(animate(els,{opacity:[0,1],y:[6,0]},{duration:.28,delay:stagger(.025)}))}
watch([page,state],enter)
onMounted(()=>{media=matchMedia('(prefers-reduced-motion: reduce)');media.addEventListener('change',stop);enter()})
onBeforeUnmount(()=>{disposed=true;generation++;stop();media?.removeEventListener('change',stop)})
function go(p:string){page.value=p;mobileNav.value=false;query.value='';notice.value=''}
function open(k:string,v?:CareVisit){opener=document.activeElement as HTMLElement;kind.value=k;detail.value=v||null;validation.value='';clientDraft.value='';careDraft.value=v?.caregiver||'';nameDraft.value='';dialog.value?.showModal()}
function close(){dialog.value?.close();opener?.focus()}
function approve(id:string,person:string){const v=visits.value.find(v=>v.id===id);if(v){v.caregiver=person;v.status='scheduled';notice.value=`${v.id} assigned to ${person} in this local demo. No caregiver was contacted.`}}
function approveAll(){replacements.value.forEach(p=>approve(p.id,p.caregiver));notice.value='Visible suggested replacements approved locally. No messages or real schedule changes.';close()}
function saveVisit(){if(!clientDraft.value.trim()){validation.value='Enter a client name.';return}const start=Number(startDraft.value);if(!Number.isFinite(start)||start<7||start>17){validation.value='Start must be between 07:00 and 17:00.';return}visits.value.push({id:'HC-'+String(visits.value.length+1).padStart(3,'0'),client:clientDraft.value.trim(),caregiver:careDraft.value||null,area:areaDraft.value,start,end:start+1,status:careDraft.value?'scheduled':'needs-cover',evv:false,note:''});notice.value='New one-hour visit added locally. No appointment was booked.';close()}
function reassign(){if(detail.value){detail.value.caregiver=careDraft.value||null;detail.value.status=careDraft.value?'scheduled':'needs-cover';notice.value='Assignment updated locally; no caregiver contacted.';close()}}
function verify(){if(detail.value){detail.value.evv=true;notice.value='Sample verification marked reviewed locally. This is not a real EVV attestation.';close()}}
function saveNote(){if(!nameDraft.value.trim()){validation.value='Enter a sample visit note.';return}if(detail.value){detail.value.note=nameDraft.value.trim();notice.value='Care note saved in this session only.';close()}}
function alertAction(id:string,v:CareVisit){if(id==='late')open('reassign',v);else if(id==='evv')open('evv',v);else{reminded.value=true;notice.value='Reminder preview recorded locally. No reminder was sent.'}}
function exportCsv(){const rows=[['Visit','Client','Caregiver','Area','Start','End','Status','EVV'],...filtered.value.map(v=>[v.id,v.client,v.caregiver||'Unassigned',v.area,careTime(v.start),careTime(v.end),v.status,v.evv?'Reviewed':'Unverified'])],csv=rows.map(row=>row.map(s=>'"'+String(s).replaceAll('"','""')+'"').join(',')).join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='meadow-sample-visits.csv';a.click();URL.revokeObjectURL(url);notice.value=`Exported ${filtered.value.length} synthetic visit rows. No private data.`}
function reset(){visits.value=makeCareVisits();area.value='All service areas';query.value='';dismissed.value=[];reminded.value=false;state.value='Ready';selectedDay.value=5;notice.value='Sample data reset.'}
</script>
<template>
<div ref="root" class="hc-app" :class="{'hc-dark':dark}"><aside class="hc-sidebar" :class="{open:mobileNav}"><a class="hc-brand" href="/home-care"><span><i class="fa-solid fa-seedling" aria-hidden="true"></i></span><div>Meadow<small>{{ agency }}</small></div></a><label class="hc-search"><i class="fa-solid fa-magnifying-glass" aria-hidden="true"></i><input v-model="query" aria-label="Search care records" placeholder="Search visits or clients" @input="page='Visits'"></label><small class="hc-group-label">Operations</small><nav aria-label="Home care operations"><button v-for="(p,i) in pages.slice(0,4)" :key="p" :class="{active:page===p}" :aria-label="p" :aria-current="page===p?'page':undefined" @click="go(p)"><i :class="['fa-solid',['fa-table-cells-large','fa-calendar-days','fa-clipboard-list','fa-bell'][i]]" aria-hidden="true"></i>{{ p }}<b v-if="p==='Alerts'&&alerts.length" class="hc-badge">{{ alerts.length }}</b></button></nav><small class="hc-group-label">People</small><nav aria-label="Care people"><button v-for="p in ['Caregivers','Clients']" :key="p" :class="{active:page===p}" @click="go(p)"><i :class="['fa-solid',p==='Caregivers'?'fa-user-group':'fa-house-user']" aria-hidden="true"></i>{{ p }}</button></nav><small class="hc-group-label">Compliance & toolkit</small><nav aria-label="Care toolkit"><button v-for="p in ['EVV','Reports','Components']" :key="p" :class="{active:page===p}" @click="go(p)"><i :class="['fa-solid',p==='EVV'?'fa-shield-halved':p==='Reports'?'fa-chart-simple':'fa-layer-group']" aria-hidden="true"></i>{{ p }}</button></nav><small class="hc-group-label">Service areas</small><div class="hc-areas"><button v-for="a in careAreas" :key="a" :aria-pressed="area===a" @click="area=area===a?'All service areas':a"><i></i>{{ a }}<small>{{ visits.filter(v=>v.area===a).length }}</small></button></div><div class="hc-sidebar-bottom"><button @click="go('Help')"><i class="fa-regular fa-circle-question" aria-hidden="true"></i> Help and support</button><button @click="go('Settings')"><i class="fa-solid fa-gear" aria-hidden="true"></i> Settings</button><div class="hc-user"><span class="hc-avatar">AC</span><div>Alex Carter<small>Care coordinator · demo</small></div></div></div></aside><div class="hc-main"><header class="hc-top"><button class="hc-menu" aria-label="Toggle care navigation" :aria-expanded="mobileNav" @click="mobileNav=!mobileNav"><i class="fa-solid fa-bars" aria-hidden="true"></i></button><span>Operations <i class="fa-solid fa-chevron-right" aria-hidden="true"></i> {{ page }}</span><div><span class="hc-clock"><i></i> MON, OCT 5 · 08:46 SAMPLE</span><button aria-label="Open activity inbox" @click="open('inbox')"><i class="fa-solid fa-inbox" aria-hidden="true"></i></button><button aria-label="Open care alerts" @click="go('Alerts')"><i class="fa-regular fa-bell" aria-hidden="true"></i><b v-if="alerts.length" class="hc-dot"></b></button></div></header><div class="hc-page"><div class="hc-heading"><div><small class="hc-eyebrow">CARE OPERATIONS / LOCAL DEMO</small><h2>{{ title }}</h2><p>{{ page==='Dashboard'?'Monday, October 5 · '+filtered.filter(v=>v.caregiver).length+' of '+filtered.length+' visits assigned. '+missing.length+' need a caregiver.':'Fictitious records. Actions stay in this browser session.' }}</p></div><div class="hc-heading-actions"><label class="hc-area-label"><i class="fa-solid fa-location-dot" aria-hidden="true"></i><select v-model="area" aria-label="Service area"><option>All service areas</option><option v-for="a in careAreas" :key="a">{{ a }}</option></select></label><button class="hc-primary" @click="open('new')"><i class="fa-solid fa-plus" aria-hidden="true"></i> New visit</button></div></div><div class="hc-demo-tools"><label>Preview state<select v-model="state"><option>Ready</option><option>Loading</option><option>Empty</option><option>Error</option></select></label><button :aria-pressed="dark" @click="dark=!dark">{{ dark?'Light':'Dark' }} theme</button><button @click="reset">Reset sample</button><span>48 sample visits · no real care decisions</span></div><div v-if="notice" class="hc-notice" role="status"><i class="fa-regular fa-circle-check" aria-hidden="true"></i>{{ notice }}<button aria-label="Dismiss care feedback" @click="notice=''">×</button></div><section v-if="state!=='Ready'" class="hc-placeholder hc-card hc-enter" :aria-busy="state==='Loading'"><h3>{{ state==='Loading'?'Loading sample visits':state==='Empty'?'No visit records':'Unable to load this preview' }}</h3><p>{{ state==='Loading'?'Manual preview only. No request is running.':state==='Empty'?'Choose another service area or restore the sample.':'No data was changed. This is a manual error-state preview.' }}</p><button @click="state='Ready'">{{ state==='Error'?'Retry preview':'Restore sample' }}</button></section><template v-else>
<template v-if="page==='Dashboard'"><section class="hc-callout hc-enter"><div><span class="hc-callout-chip"><i class="fa-solid fa-user-clock" aria-hidden="true"></i> CALL-OUT · 08:31 SAMPLE</span><h3>{{ missing.length?'A caregiver called out.\n'+missing.length+' visits need cover today.':'Every visible visit has an assignment.' }}</h3><p>{{ missing.length?'Suggested replacements are ready for local review. You stay in control.':'The sample plan is covered. Assignment does not prove a visit occurred.' }}</p><div><button @click="open('replacements')">Review replacements <i class="fa-solid fa-chevron-right" aria-hidden="true"></i></button><button class="hc-glass" @click="go('Schedule')">See the day</button></div></div><div class="hc-proposals"><small>Suggested replacements</small><button v-for="p in replacements" :key="p.id" @click="open('replacements')"><span>{{ careTime(p.visit!.start) }}</span><strong>{{ p.visit!.client }}</strong><i class="fa-solid fa-angle-right" aria-hidden="true"></i><span class="hc-mini-avatar">{{ p.caregiver.split(' ').map(s=>s[0]).join('') }}</span><span>{{ p.caregiver }}</span><b>{{ p.score }}%</b></button><p v-if="!replacements.length">No pending suggestions in this view.</p><small>Illustrative match scores, not clinical recommendations.</small></div></section><div class="hc-kpis"><HomeCareKpi label="Scheduled today" :value="filtered.length" detail="14 caregivers in the sample roster"/><HomeCareKpi label="Assigned" :value="filtered.filter(v=>v.caregiver).length" :detail="missing.length+' need a caregiver'" tone="pink"/><HomeCareKpi label="In progress" :value="live.length" :detail="done.length+' completed in this view'" tone="green"/><HomeCareKpi label="At risk" :value="late.length" detail="Sample arrival needs review" tone="yellow"/></div><div class="hc-dashboard-grid"><HomeCareCoverage :visits="filtered" @open="id=>open('detail',visits.find(v=>v.id===id))"/><div class="hc-right-stack"><section class="hc-card hc-enter"><header><h3><i class="fa-regular fa-flag" aria-hidden="true"></i> Needs attention <b class="hc-badge">{{ alerts.length }}</b></h3><button class="hc-link" @click="go('Alerts')">All alerts ›</button></header><div v-for="a in alerts" :key="a.id" class="hc-alert-row"><span class="hc-alert-icon" :class="a.id"><i :class="['fa-solid',a.id==='late'?'fa-clock':a.id==='evv'?'fa-location-dot':'fa-clipboard']" aria-hidden="true"></i></span><div><strong>{{ a.title }}</strong><small>{{ a.visit!.client }} · {{ a.visit!.id }}</small></div><button @click="alertAction(a.id,a.visit!)">{{ a.id==='note'&&reminded?'Previewed':a.action }}</button></div><p v-if="!alerts.length" class="hc-pad">No unresolved alerts in this view.</p></section><section class="hc-card hc-enter"><header><h3><i class="fa-solid fa-wave-square" aria-hidden="true"></i> Live visits</h3><span class="hc-pill">{{ live.length }} in progress</span></header><button v-for="v in live" :key="v.id" class="hc-live-row" @click="open('detail',v)"><span class="hc-avatar">{{ v.caregiver?.split(' ').map(s=>s[0]).join('') }}</span><span><strong>{{ v.caregiver }}</strong><small>{{ v.client }} · started {{ careTime(v.start) }}</small></span><span><small>ENDS {{ careTime(v.end) }}</small><i class="hc-mini-bars"><b v-for="i in 10" :key="i" :class="{filled:i<7}"></b></i></span></button><p v-if="!live.length" class="hc-pad">No live visits in this view.</p></section></div></div></template>
<template v-else-if="page==='Schedule'||page==='Visits'"><section v-if="page==='Schedule'" class="hc-card hc-enter"><header><h3>Monday, October 5, 2026</h3><span class="hc-pill">Fixed sample date</span></header><p class="hc-pad">A day plan, not a real calendar integration. Visit times are local wall-clock fixtures with no timezone conversion.</p><HomeCareCoverage :visits="filtered" @open="id=>open('detail',visits.find(v=>v.id===id))"/></section><section class="hc-card hc-enter"><header><h3>{{ page==='Visits'?'Visit directory':'Day assignments' }} · {{ filtered.length }}</h3><label><input v-model="query" aria-label="Filter visit list" placeholder="Find client, caregiver or ID"></label><button @click="exportCsv">Export sample CSV</button></header><div class="hc-table-wrap"><table><thead><tr><th>Visit / client</th><th>Caregiver</th><th>Time</th><th>Area</th><th>Status</th><th>Detail</th></tr></thead><tbody><tr v-for="v in filtered" :key="v.id"><th><small>{{ v.id }}</small>{{ v.client }}</th><td>{{ v.caregiver||'Unassigned' }}</td><td>{{ careTime(v.start) }}–{{ careTime(v.end) }}</td><td>{{ v.area }}</td><td><span class="hc-state-badge" :class="v.status">{{ v.status.replaceAll('-',' ') }}</span></td><td><button :aria-label="'View '+v.id" @click="open('detail',v)">View</button></td></tr></tbody></table><p v-if="!filtered.length" class="hc-pad">No visits match these filters.</p></div></section></template>
<template v-else-if="page==='Alerts'"><section class="hc-card hc-enter"><header><h3>Review queue · {{ alerts.length }}</h3><span>Local sample exceptions</span></header><article v-for="a in alerts" :key="a.id" class="hc-alert-full"><div><span class="hc-pill">{{ a.id.toUpperCase() }}</span><h3>{{ a.title }}</h3><p>{{ a.text }}</p><small>{{ a.visit!.client }} · {{ a.visit!.id }}</small></div><div><button @click="alertAction(a.id,a.visit!)">{{ a.action }}</button><button @click="dismissed.push(a.id);notice='Alert dismissed locally. Reset restores it.'">Dismiss locally</button></div></article><p v-if="!alerts.length" class="hc-pad">No unresolved alerts. Reset restores the sample queue.</p></section></template>
<template v-else-if="page==='Caregivers'"><div class="hc-person-grid"><article v-for="p in carePeople.filter(p=>area==='All service areas'||p.area===area)" :key="p.name" class="hc-card hc-person hc-enter"><span class="hc-avatar">{{ p.initials }}</span><h3>{{ p.name }}</h3><p>{{ p.skill }}</p><span class="hc-pill">{{ p.status }}</span><small>{{ p.area }} · {{ visits.filter(v=>v.caregiver===p.name).length }} assigned visits</small><button @click="query=p.name;page='Visits'">View assignments</button></article></div><p class="hc-footnote">Availability and qualifications are synthetic. This demo does not check overlapping assignments, travel or clinical suitability.</p></template>
<template v-else-if="page==='Clients'"><div class="hc-person-grid"><article v-for="c in clients" :key="c" class="hc-card hc-person hc-enter"><span class="hc-avatar">{{ c.split(' ').map(s=>s[0]).join('') }}</span><h3>{{ c }}</h3><p>Sample care plan · no private health data</p><small>{{ filtered.filter(v=>v.client===c).length }} visits in this view</small><button @click="query=c;page='Visits'">View care visits</button></article></div></template>
<template v-else-if="page==='EVV'"><section class="hc-card hc-enter"><header><h3>Electronic visit verification preview</h3><span>{{ filtered.filter(v=>!v.evv).length }} unverified</span></header><p class="hc-pad">Review is a local display flag only. No GPS, signature, payer filing or regulatory attestation is performed.</p><div v-for="v in filtered.filter(v=>!v.evv)" :key="v.id" class="hc-alert-row"><div><strong>{{ v.client }}</strong><small>{{ v.id }} · {{ v.caregiver||'Unassigned' }}</small></div><button @click="open('evv',v)">Review {{ v.id }}</button></div><p v-if="!filtered.some(v=>!v.evv)" class="hc-pad">All visible sample verification flags are reviewed.</p></section></template>
<template v-else-if="page==='Reports'"><div class="hc-kpis"><HomeCareKpi label="Visit records" :value="filtered.length" detail="Current service-area filter"/><HomeCareKpi label="Assignment coverage" :value="filtered.length?Math.round(filtered.filter(v=>v.caregiver).length/filtered.length*100):0" detail="Percent of records with a caregiver"/><HomeCareKpi label="Verified flags" :value="filtered.filter(v=>v.evv).length" detail="Sample local flags only"/><HomeCareKpi label="Care notes" :value="filtered.filter(v=>v.note).length" detail="Nonempty session notes"/></div><section class="hc-card hc-enter"><header><h3>Area summary</h3><button @click="exportCsv">Download sample report</button></header><div class="hc-table-wrap"><table><thead><tr><th>Area</th><th>Visits</th><th>Assigned</th><th>Need cover</th></tr></thead><tbody><tr v-for="a in careAreas.filter(a=>area==='All service areas'||a===area)" :key="a"><th>{{ a }}</th><td>{{ filtered.filter(v=>v.area===a).length }}</td><td>{{ filtered.filter(v=>v.area===a&&v.caregiver).length }}</td><td>{{ filtered.filter(v=>v.area===a&&!v.caregiver).length }}</td></tr></tbody></table></div></section></template>
<template v-else-if="page==='Components'"><section class="hc-card hc-enter hc-catalog"><h3>Foundations & reusable parts</h3><p>Cool slate surfaces, ink typography, blue coverage, lavender completion, pink gaps and amber risk. Status text is always shown with color.</p><div class="hc-token-row"><span v-for="s in ['covered','complete','uncovered','risk']" :key="s"><i :class="s"></i>{{ s }}</span></div><h3>Buttons and badges</h3><div class="hc-heading-actions"><button class="hc-primary" @click="open('new')">Primary · new visit</button><button @click="open('replacements')">Secondary · review</button><button disabled>Disabled</button><span class="hc-state-badge completed">Completed</span><span class="hc-state-badge needs-cover">Needs cover</span></div><h3>Reusable KPI card</h3><HomeCareKpi label="Sample capacity" :value="48" detail="A reusable presentation component"/><h3>Feedback and dialogs</h3><button @click="notice='Inline status feedback preview.'">Show status feedback</button><button @click="open('detail',filtered[0])">Open visit detail</button><p>Coverage matrix, assignment banner, proposal rows, attention queue, live visit rows, people cards, table, filters, native modal and state previews are all used in the operational screens. See the component guide for exact APIs.</p><a href="/home-care/components">Read component documentation →</a></section></template>
<template v-else-if="page==='Settings'"><form class="hc-card hc-settings hc-enter" @submit.prevent="settingsSaved=true;notice='Preferences saved locally for this session only.'"><h3>Workspace preferences</h3><label>Agency display name<input v-model="agency" required maxlength="60"></label><label class="hc-checkbox"><input v-model="notify" type="checkbox"> Show sample in-app notifications</label><p>This does not send messages or change real notifications.</p><button class="hc-primary">Save local preferences</button><span v-if="settingsSaved">Saved in session.</span></form></template>
<template v-else><section class="hc-card hc-catalog hc-enter"><h3>A calm place to coordinate care</h3><p>This is an original working design template inspired by the visible dashboard reference. Every person and record is fictitious. It is not a clinical recommendation, staffing optimizer, EVV service or care-delivery system.</p><details><summary>What can I try?</summary><p>Approve replacements, inspect coverage, create a sample visit, change an assignment, review sample EVV flags, save care notes, filter areas, export synthetic CSV and preview states.</p></details><details><summary>What stays local?</summary><p>All actions. No caregiver, client or provider is contacted. Reset restores visit fixtures; reloading also resets them.</p></details><a href="/home-care/components">Component APIs and integration limits</a></section></template>
</template><footer class="hc-app-footer">Meadow · original template · fictitious data · no real care actions <a href="/home-care/components">Component guide</a></footer></div></div>
<dialog ref="dialog" class="hc-dialog" aria-labelledby="hc-dialog-title" @close="kind=''" @cancel="kind=''" @click="e=>{if(e.target===dialog)close()}"><header><h3 id="hc-dialog-title">{{ kind==='new'?'New sample visit':kind==='replacements'?'Review suggested cover':kind==='reassign'?'Change local assignment':kind==='evv'?'Review verification preview':kind==='note'?'Local visit note':kind==='inbox'?'Activity inbox':'Visit details' }}</h3><button type="button" aria-label="Close care dialog" @click="close">×</button></header><div class="hc-dialog-body"><p class="hc-footnote">Sample workflow only. No real appointment, message or attestation.</p><template v-if="kind==='new'"><form @submit.prevent="saveVisit"><label>Client name<input v-model="clientDraft" required maxlength="60"></label><label>Start hour<select v-model="startDraft"><option v-for="h in 11" :key="h" :value="h+6">{{ careTime(h+6) }}</option></select></label><label>Service area<select v-model="areaDraft"><option v-for="a in careAreas" :key="a">{{ a }}</option></select></label><label>Caregiver<select v-model="careDraft" aria-label="Caregiver"><option value="">Unassigned</option><option v-for="p in carePeople.filter(p=>p.status!=='Called out')" :key="p.name">{{ p.name }}</option></select></label><p v-if="validation" role="alert">{{ validation }}</p><button class="hc-primary">Create local visit</button></form></template><template v-else-if="kind==='replacements'"><p>Illustrative candidate scores. No availability, travel or qualification checks are performed. Review each suggestion before any real staffing action.</p><article v-for="p in replacements" :key="p.id" class="hc-replacement"><strong>{{ p.visit!.client }} · {{ careTime(p.visit!.start) }}</strong><p>{{ p.caregiver }} <span class="hc-pill">{{ p.score }}% sample match</span></p><button :aria-label="'Approve '+p.id" @click="approve(p.id,p.caregiver)">Approve locally</button></article><p v-if="!replacements.length">No pending suggestions in this area.</p><button v-if="replacements.length" class="hc-primary" @click="approveAll">Approve visible suggestions locally</button></template><template v-else-if="detail"><dl class="hc-detail-grid"><div v-for="(v,k) in {Visit:detail.id,Client:detail.client,Caregiver:detail.caregiver||'Unassigned',Area:detail.area,Time:careTime(detail.start)+'–'+careTime(detail.end),Status:detail.status,Verification:detail.evv?'Reviewed sample flag':'Unverified'}" :key="k"><dt>{{ k }}</dt><dd>{{ v }}</dd></div></dl><template v-if="kind==='reassign'"><label>Assign caregiver<select v-model="careDraft"><option value="">Unassigned</option><option v-for="p in carePeople.filter(p=>p.status!=='Called out')" :key="p.name">{{ p.name }}</option></select></label><button class="hc-primary" @click="reassign">Save local assignment</button></template><template v-else-if="kind==='evv'"><p>No actual location or payer records are available. This button only changes the demo flag.</p><button class="hc-primary" @click="verify">Mark sample flag reviewed</button></template><template v-else-if="kind==='note'"><form @submit.prevent="saveNote"><label>Sample care note<textarea v-model="nameDraft" required maxlength="500"></textarea></label><p v-if="validation" role="alert">{{ validation }}</p><button class="hc-primary">Save session note</button></form></template><template v-else><p><strong>Care note</strong><br>{{ detail.note||'No note recorded.' }}</p><div class="hc-heading-actions"><button @click="kind='reassign'">Change assignment</button><button @click="kind='note'">Add care note</button><button @click="kind='evv'">Review EVV flag</button></div></template></template><template v-else-if="kind==='inbox'"><p v-if="notify">Sample coordinator update: three candidate replacements were prepared for your review.</p><p v-else>Sample notifications are hidden by your local preference.</p><button @click="close();go('Alerts')">Review exceptions</button></template><template v-else><p>No visit matches the current view.</p></template></div></dialog>
</div>
</template>
